__NUXT_JSONP__("/jp/stay", (function(a,b,c,d,e,f,g,h,i){return {data:[{details:{slug:"jp",pageTitle:"滞在環境 | Mentor Language Institute",pageDescription:"MLIは学生用ハウンジングサービスをU.S.サポートサービス社を通して提供しています。",title:"滞在環境",subtitle:["MLIは学生用ハウンジングサービスをU.S.サポートサービス社を通して提供しています。詳細はこちらのリンクよりご確認ください。 \u003Ca href=\"www.usssinc.net\" target=\"_blank\"\u003Ewww.usssinc.net\u003C\u002Fa\u003E"],image:"\u002Fimages\u002Flocation\u002Faccommodations\u002Faccommodation-1.jpg",gallery:["\u002Fimages\u002Flocation\u002Faccommodations\u002Faccommodation-2.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Faccommodation-3.jpg"],note:"留学生は自分のスタイルに合わせてホームステイか学生寮から選べます。",types:[{title:"学生寮",description:["留学生同士、交流する機会が増えます。自由な環境、学校で出来た友達と様々な場所を巡りたい方は学生寮がお勧めです。"],lists:["\u003Cb\u003E部屋\u003C\u002Fb\u003E : 1人部屋～4人部屋から選択","\u003Cb\u003E食事\u003C\u002Fb\u003E : 自分で手配","\u003Cb\u003Eプライバシー\u003C\u002Fb\u003E : ホームステイと比較して自由（寮則はあります）","\u003Cb\u003E通学\u003C\u002Fb\u003E : 徒歩またはバスで平均20分程度"],gallery:["\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-1.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-2.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-3.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-4.jpg"],prices:[{title:"学生寮の料金",maxCol:4,table:{title:"入居費: $200\u003Cbr \u002F\u003E18歳未満の生徒様は、家賃が通常料金の約10%上乗せとなります。",thead:[b,"個室","\tシェアルーム（2人）","シェアルーム（4人）"],tbody:[[c,a,a,a],[d,"$550","$410",a],[e,"$1,100","$820","$600"],[f,"$1,650","$1,230","$900"],[g,"$2,200","$1,640","$1,200"],[h,"$4,160","$2,960","$2,160"],[i,"$6,240","$4,440","$3,240"]]}}]},{title:"ホームステイ",description:["ホームステイは活きた英語に触れられる、アメリカ人の生活を知るもっとも良 い手段です。一緒に食卓を囲み、様々な会話を交わす事、おのおのの家庭にあ るルールを知ることは忘れられない体験になるでしょう。"],lists:["\u003Cb\u003E部屋\u003C\u002Fb\u003E : 1人部屋。","\u003Cb\u003E食事\u003C\u002Fb\u003E : 1日2回、朝晩の食事が提供","\u003Cb\u003Eプライバシー\u003C\u002Fb\u003E : 家庭によって異なるが、多くはハウスルールがある。","\u003Cb\u003E通学\u003C\u002Fb\u003E : 基本バスで30-45分程度"],gallery:["\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-1.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-2.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-3.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-4.jpg"],prices:[{title:"ホームステイの料金",table:{title:"入居費：$300\u003Cbr \u002F\u003E18歳未満の生徒様は、家賃が通常料金の約10%上乗せとなります。",maxCol:2,thead:[b,"一人部屋","シェア"],tbody:[[c,a,a],[d,"$436","$384"],[e,"$872","$768"],[f,"$1,308","$1,152"],[g,"$1,744","$1,536"],[h,"$3,160","$2,904"],[i,"$4,740","$4,356"]]}}]}],japanese:{title:"長期留学生へスタッフからのアドバイス",description:["渡米して間もない留学生が、到着していきなり滞在先探しをするのはお勧めできません。アメリカは最低でも1年間の長期契約が求められますし、ソーシャルセキュリティー（納税者番号）のない学生さんが自分でアパートを借りるのは簡単ではありません。","借りる場所や契約などの失敗を避けるためにも、まずはMLIの滞在先に入り情報を集める。その後、アパートやシェアメイトを自分の目で見て探すのがお勧めです。"]},comments:{title:"\u003Ci class='bi bi-arrow-right'\u003E\u003C\u002Fi\u003E どちらのタイプが自分に合うかの相談、空き状況の確認は日本事務局まで",description:["※滞在先の提供はU.S. Support Service Inc、または他ホームステイ斡旋会社が提供する場合があります。"]},dir:"\u002Fstay",path:"\u002Fstay\u002Fjp",extension:".json",createdAt:"2026-10-22T16:31:31.098Z",updatedAt:"2025-05-26T12:06:27.919Z"}}],fetch:{},mutations:void 0}}("$300","","\u003Cb\u003E保証金**\u003C\u002Fb\u003E","1 週間","2 週間","3 週間","4 週間","8 週間","12 週間")));